import{_ as n,c as a,o as l,ag as o}from"./chunks/framework.wXsWYe_K.js";const e="/assets/jdk.BFpl5HCn.png",t="/assets/jenkins.7I6FYGUg.png",p="/assets/chinese.D47h2WQ4.png",i="/assets/safeWay.Be7hXvND.png",r="/assets/loginUser.BxwT4lbh.png",c="/assets/addUser.Dw1x84m9.png",m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"views/frontEnd/tools/jenkins/index.md","filePath":"views/frontEnd/tools/jenkins/index.md"}'),d={name:"views/frontEnd/tools/jenkins/index.md"};function D(y,s,B,F,u,k){return l(),a("div",null,s[0]||(s[0]=[o('<h2 id="产生背景" tabindex="-1">产生背景 <a class="header-anchor" href="#产生背景" aria-label="Permalink to &quot;产生背景&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">背景</p><p>原来公司内部的打包流程：本地打包-&gt;登录服务器-&gt;上传压缩包-&gt;解压缩</p><p>引发的问题：</p><ul><li>保持依赖的正确性；本地环境会影响代码，有的依赖升级了，但是package.json里面的依赖还是原来的，实际里面的依赖已经不是了，这样的话，如果更换了前端的环境就有可能有问题</li><li>本地打包影响开发编码，会浪费很多时间在发包部署上面</li></ul></div><p>为了解决这个问题，我在自己本地部署了一个jenkins,给组内的前端成员进行打包，接下来就简单梳理下：</p><p>window下的jenkins如何部署？</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>想要安装jenkins,就必须要安装jdk和jenkins的安装包</p><ul><li>jdk21: <a href="https://www.oracle.com/cn/java/technologies/downloads/#jdk21-windows" target="_blank" rel="noreferrer">https://www.oracle.com/cn/java/technologies/downloads/#jdk21-windows</a><img src="'+e+'" alt="alt text" loading="lazy"></li><li>jenkins: <a href="https://www.jenkins.io/zh/download/" target="_blank" rel="noreferrer">https://www.jenkins.io/zh/download/</a><img src="'+t+'" alt="alt text" loading="lazy"></li></ul></div><h2 id="jenkins的基本使用" tabindex="-1">jenkins的基本使用 <a class="header-anchor" href="#jenkins的基本使用" aria-label="Permalink to &quot;jenkins的基本使用&quot;">​</a></h2><p>安装完推荐的插件以后，我们进入到当前的jenkins中：</p><div class="info custom-block"><p class="custom-block-title">开始</p><p>进入到jenkins中，我们发现一个问题，汉化仅仅汉化</p></div><h2 id="jenkins-部分汉化-应该怎么解决" tabindex="-1">jenkins 部分汉化，应该怎么解决？ <a class="header-anchor" href="#jenkins-部分汉化-应该怎么解决" aria-label="Permalink to &quot;jenkins 部分汉化，应该怎么解决？&quot;">​</a></h2><p>在window上面安装jenkins，并且安装了汉化插件，还是出现汉化不全的情况： 在linux安装相同版本是完美汉化的，在window上面确实不对的，所以猜测应该是window和linux的差异： linux 的语言默认是c.utf-8,c.utf-8是默认的语言环境，而有的机器是en_US.utf-8</p><ul><li>于是在window的jenkins的安装目录修改配置文件jenkins.xml文件</li><li>在大概40行的位置，java启动参数里面增加 -Duer.language=C.UTF-8参数来指定语言，重启jenkins <img src="'+p+`" alt="alt text" loading="lazy"></li></ul><h2 id="怎么解决npm私服配合jenkins自动化构建" tabindex="-1">怎么解决npm私服配合jenkins自动化构建 <a class="header-anchor" href="#怎么解决npm私服配合jenkins自动化构建" aria-label="Permalink to &quot;怎么解决npm私服配合jenkins自动化构建&quot;">​</a></h2><h2 id="jdk配置环境变量" tabindex="-1">jdk配置环境变量 <a class="header-anchor" href="#jdk配置环境变量" aria-label="Permalink to &quot;jdk配置环境变量&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>安装步骤：下载以后就直接选中文件夹进行安装就好了</p><ul><li>我的电脑右键，打开属性</li><li>高级系统设置，找到环境变量</li><li>在系统变量上新建 变量名：JAVA_HOME 变量值：D:\\jdk（jdk的安装路径）</li><li>在系统变量上新建 变量名：CLASSPATH 变量值：.;%JAVA_HOME%\\lib;%JAVA_HOME%\\lib\\tools.jar</li><li>在系统变量上点击path,新建一个值：%JAVA_HOME%\\bin</li><li>最后打开cmd,java -verison,测试打印结果，输出jdk的版本号就是成功了</li></ul></div><h2 id="window家庭版不能打开本地策略-解决方案" tabindex="-1">window家庭版不能打开本地策略，解决方案 <a class="header-anchor" href="#window家庭版不能打开本地策略-解决方案" aria-label="Permalink to &quot;window家庭版不能打开本地策略，解决方案&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>1.在桌面创建一个文本文件 aaa.txt</li><li>2.编辑文本,填充代码</li></ul><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span style="color:#89DDFF;">@</span><span style="color:#BABED8;">echo off</span></span>
<span class="line"><span style="color:#BABED8;">pushd </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">%~dp0</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#BABED8;">dir </span><span style="color:#89DDFF;">/</span><span style="color:#BABED8;">b </span><span style="color:#FFCB6B;">C</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;">\\Windows\\servicing\\Packages\\Microsoft</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">Windows</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">GroupPolicy</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">ClientExtensions</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">Package</span><span style="color:#89DDFF;">~</span><span style="color:#F78C6C;">3</span><span style="color:#89DDFF;">*.</span><span style="color:#BABED8;">mum </span><span style="color:#89DDFF;">&gt;</span><span style="color:#BABED8;">List</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">txt</span></span>
<span class="line"><span style="color:#BABED8;">dir </span><span style="color:#89DDFF;">/</span><span style="color:#BABED8;">b </span><span style="color:#FFCB6B;">C</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;">\\Windows\\servicing\\Packages\\Microsoft</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">Windows</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">GroupPolicy</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">ClientTools</span><span style="color:#89DDFF;">-</span><span style="color:#BABED8;">Package</span><span style="color:#89DDFF;">~</span><span style="color:#F78C6C;">3</span><span style="color:#89DDFF;">*.</span><span style="color:#BABED8;">mum </span><span style="color:#89DDFF;">&gt;&gt;</span><span style="color:#BABED8;">List</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">txt</span></span>
<span class="line"><span style="color:#BABED8;">for </span><span style="color:#89DDFF;">/</span><span style="color:#BABED8;">f </span><span style="color:#89DDFF;">%%</span><span style="color:#BABED8;">i </span><span style="color:#89DDFF;">in</span><span style="color:#BABED8;"> (</span><span style="color:#89DDFF;">&#39;</span><span style="color:#C3E88D;">findstr /i . List.txt 2^&gt;nul</span><span style="color:#89DDFF;">&#39;</span><span style="color:#BABED8;">) </span><span style="color:#89DDFF;font-style:italic;">do</span><span style="color:#BABED8;"> dism </span><span style="color:#89DDFF;">/</span><span style="color:#BABED8;">online </span><span style="color:#89DDFF;">/</span><span style="color:#BABED8;">norestart </span><span style="color:#89DDFF;">/</span><span style="color:#BABED8;">add</span><span style="color:#89DDFF;">-</span><span style="color:#89DDFF;font-style:italic;">package</span><span style="color:#BABED8;">:</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">C:</span><span style="color:#BABED8;">\\W</span><span style="color:#C3E88D;">indows</span><span style="color:#BABED8;">\\s</span><span style="color:#C3E88D;">ervicing</span><span style="color:#BABED8;">\\P</span><span style="color:#C3E88D;">ackages</span><span style="color:#BABED8;">\\%</span><span style="color:#C3E88D;">%i</span><span style="color:#89DDFF;">&quot;</span></span>
<span class="line"><span style="color:#BABED8;">pause</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div></div><ul><li>修改后缀名 .txt -&gt; .cmd</li><li>4.以管理员权限运行</li><li>5.等待安装</li><li>6.win+r 打开运行，输入gpedit.msc即可运行</li></ul><h2 id="有本地安全策略-但是安装jenkins的时候-采用登录账户验证不通过怎么解决" tabindex="-1">有本地安全策略，但是安装jenkins的时候，采用登录账户验证不通过怎么解决？ <a class="header-anchor" href="#有本地安全策略-但是安装jenkins的时候-采用登录账户验证不通过怎么解决" aria-label="Permalink to &quot;有本地安全策略，但是安装jenkins的时候，采用登录账户验证不通过怎么解决？&quot;">​</a></h2><p><img src="`+i+'" alt="alt text" loading="lazy"> 找到你的登录账户信息： <img src="'+r+'" alt="alt text" loading="lazy"> 添加用户： <img src="'+c+'" alt="alt text" loading="lazy"> 这样就可以用这个账号登录了</p><h2 id="参考连接" tabindex="-1">参考连接： <a class="header-anchor" href="#参考连接" aria-label="Permalink to &quot;参考连接：&quot;">​</a></h2><ul><li><a href="https://juejin.cn/post/7171741567751815199?searchId=20250612140340EFE29A46BCE81DBF9E13" target="_blank" rel="noreferrer">https://juejin.cn/post/7171741567751815199?searchId=20250612140340EFE29A46BCE81DBF9E13</a></li><li><a href="https://blog.csdn.net/u013571586/article/details/126976005" target="_blank" rel="noreferrer">https://blog.csdn.net/u013571586/article/details/126976005</a></li></ul>',21)]))}const E=n(d,[["render",D]]);export{m as __pageData,E as default};
